    @Test(timeout = 4000)
    public void toStringOfNegatedRangeStartsWithCaret() throws Throwable {
        CharRange negatedRange = CharRange.isNotIn('G', 'j');

        // Call once to populate the cached value, then read it back.
        negatedRange.toString();
        String text = negatedRange.toString();

        assertNotNull(text);
        assertEquals("^G-j", text);
    }

    @Test(timeout = 4000)
    public void toStringOfSingleCharacterRangeIsJustThatCharacter() throws Throwable {
        CharRange singleChar = CharRange.isIn('O', 'O');

        String text = singleChar.toString();

        assertEquals("O", text);
        assertNotNull(text);
    }

