    @Test(timeout = 4000)
    public void equalRangesAreEqual() throws Throwable {
        CharRange rangeA = CharRange.is('y');
        CharRange rangeB = CharRange.is('y');

        boolean equal = rangeB.equals(rangeA);

        assertEquals('y', rangeB.getEnd());
        assertEquals('y', rangeB.getStart());
        assertFalse(rangeB.isNegated());
        assertTrue(equal);
    }

    @Test(timeout = 4000)
    public void negatedAndPlainRangeOverSameCharAreNotEqual() throws Throwable {
        CharRange negatedQuote = CharRange.isNotIn('"', '"');
        CharRange plainQuote = CharRange.is('"');

        boolean equal = plainQuote.equals(negatedQuote);

        assertEquals('"', negatedQuote.getStart());
        assertFalse(equal);
        assertEquals('"', plainQuote.getStart());
        assertEquals('"', negatedQuote.getEnd());
        assertEquals('"', plainQuote.getEnd());
    }

    @Test(timeout = 4000)
    public void rangesWithDifferentBoundsAreNotEqual() throws Throwable {
        // 'Ý' > 'Y' and 'Þ' > 'V', so both factories reverse the bounds.
        CharRange negatedRange = CharRange.isNotIn('Ý', 'Y');
        CharRange plainRange = CharRange.isIn('Þ', 'V');

        boolean equal = plainRange.equals(negatedRange);

        assertFalse(equal);
        assertEquals('Þ', plainRange.getEnd());
        assertEquals('V', plainRange.getStart());
        assertEquals('Ý', negatedRange.getEnd());
        assertEquals('Y', negatedRange.getStart());
    }

    @Test(timeout = 4000)
    public void negatedSingleCharAndPlainRangeAreNotEqual() throws Throwable {
        CharRange negatedTwo = CharRange.isNot('2');
        CharRange plainRange = CharRange.isIn('2', 'U');

        boolean equal = plainRange.equals(negatedTwo);

        assertTrue(negatedTwo.isNegated());
        assertEquals('2', plainRange.getStart());
        assertEquals('U', plainRange.getEnd());
        assertFalse(equal);
        assertEquals('2', negatedTwo.getStart());
        assertEquals('2', negatedTwo.getEnd());
    }

    @Test(timeout = 4000)
    public void rangeEqualsItself() throws Throwable {
        CharRange negatedPipe = CharRange.isNot('|');

        boolean equal = negatedPipe.equals(negatedPipe);

        assertTrue(equal);
        assertTrue(negatedPipe.isNegated());
        assertEquals('|', negatedPipe.getStart());
        assertEquals('|', negatedPipe.getEnd());
    }

    @Test(timeout = 4000)
    public void rangeIsNotEqualToArbitraryObject() throws Throwable {
        CharRange singleChar = CharRange.isIn('O', 'O');
        Object other = new Object();

        boolean equal = singleChar.equals(other);

        assertEquals('O', singleChar.getStart());
        assertFalse(equal);
        assertEquals('O', singleChar.getEnd());
    }

