    @Test(timeout = 4000)
    public void plainRangeDoesNotContainCharacterOutsideIt() throws Throwable {
        CharRange range = CharRange.isIn('2', 'U');
        CharRange tilde = CharRange.is('~');

        boolean contains = range.contains(tilde);

        assertEquals('2', range.getStart());
        assertEquals('~', tilde.getStart());
        assertEquals('U', range.getEnd());
        assertEquals('~', tilde.getEnd());
        assertFalse(tilde.isNegated());
        assertFalse(contains);
    }

    @Test(timeout = 4000)
    public void singleCharRangeDoesNotContainDifferentChar() throws Throwable {
        CharRange rangeY = CharRange.isIn('y', 'y');
        CharRange charD = CharRange.is('D');

        boolean contains = rangeY.contains(charD);

        assertFalse(charD.isNegated());
        assertEquals('y', rangeY.getEnd());
        assertEquals('D', charD.getStart());
        assertFalse(contains);
        assertEquals('y', rangeY.getStart());
        assertEquals('D', charD.getEnd());
    }

    @Test(timeout = 4000)
    public void plainRangeDoesNotContainNegatedRange() throws Throwable {
        CharRange negatedTwo = CharRange.isNot('2');
