        CharRange plainNull = CharRange.is('�');

        boolean contains = plainNull.contains(negatedNull);

        assertEquals('�', plainNull.getStart());
        assertFalse(contains);
        assertEquals('�', negatedNull.getStart());
        assertEquals('�', plainNull.getEnd());
        assertEquals('�', negatedNull.getEnd());
    }

    @Test(timeout = 4000)
    public void negatedSingleCharDoesNotContainPlainRangeOverSameChar() throws Throwable {
        CharRange negatedSpace = CharRange.isNot(' ');
        CharRange plainSpace = CharRange.isIn(' ', ' ');

        boolean contains = negatedSpace.contains(plainSpace);

        assertEquals(' ', plainSpace.getEnd());
        assertEquals(' ', negatedSpace.getStart());
        assertEquals(' ', negatedSpace.getEnd());
        assertEquals(' ', plainSpace.getStart());
        assertFalse(contains);
    }

    @Test(timeout = 4000)
    public void negatedRangeContainsCharOutsideTheExcludedSpan() throws Throwable {
        CharRange negatedHighRange = CharRange.isNotIn('T', '￿');
        CharRange charJ = CharRange.is('J');

        // 'J' is below the excluded T..FFFF span, so the negated range contains it.
        boolean contains = negatedHighRange.contains(charJ);

        assertEquals('J', charJ.getEnd());
        assertTrue(contains);
        assertEquals('￿', negatedHighRange.getEnd());
        assertEquals('J', charJ.getStart());
        assertEquals('T', negatedHighRange.getStart());
    }

