        CharRange negatedOne = CharRange.isNot('1');
        CharRange negatedRange = CharRange.isNotIn('T', 'J');

        boolean contains = negatedOne.contains(negatedRange);

        assertEquals('J', negatedRange.getStart());
        assertEquals('T', negatedRange.getEnd());
        assertEquals('1', negatedOne.getStart());
        assertFalse(contains);
        assertTrue(negatedOne.isNegated());
        assertEquals('1', negatedOne.getEnd());
    }

